begin;
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',message;end if;end $$;
insert into auth.users(id,email,is_anonymous) values('fd020000-0000-4000-8000-000000000001','financial-custom@example.invalid',false);
set local role authenticated;
select set_config('request.jwt.claim.sub','fd020000-0000-4000-8000-000000000001',true);
select public.setup_business('Disposable configured financial types','Owner');
reset role;
do $$declare t uuid:=app_private.current_tenant_id();w uuid;id uuid;entry uuid;k uuid:=gen_random_uuid();r jsonb;body jsonb;d date:=(now() at time zone 'Asia/Dhaka')::date;asset uuid;report jsonb;begin
 select wallet_id into w from public.get_payment_wallets() where type='cash';
 id:=(public.save_financial_type(jsonb_build_object('name','Electricity','account','operating_expense','allocations',jsonb_build_object('lpg',70,'stove',30)))->>'type_id')::uuid;
 body:=jsonb_build_object('type_id',id,'expected_revision',1,'wallet_id',w,'amount',10000,'date',d,'description','Independent 70/30 bill');
 r:=public.record_financial_entry(body,k);entry:=(r->>'entry_id')::uuid;
 perform pg_temp.assert(public.record_financial_entry(body,k)=r,'Custom money retry retains original response');
 perform pg_temp.assert((select balance=-10000 and (business_balances->>'lpg')::numeric=-7000 and (business_balances->>'stove')::numeric=-3000 from public.wallets where tenant_id=t and wallet_id=w),'Electricity allocated as independently expected 7000 and 3000');
 perform pg_temp.assert((select count(*)=1 from public.financial_entries where tenant_id=t and type_id=id),'Custom retries do not duplicate recognition');
 perform public.save_financial_type(jsonb_build_object('type_id',id,'revision',1,'name','Electricity revised','account','operating_expense','allocations',jsonb_build_object('lpg',50,'stove',50)));
 perform pg_temp.assert((select allocations='{"lpg":70,"stove":30}'::jsonb and type_name='Electricity' from public.financial_entries where tenant_id=t and entry_id=entry),'Editing defaults preserves historical type/allocation snapshot');
 begin perform public.record_financial_entry(body,gen_random_uuid());raise exception 'FAIL: stale type revision accepted';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;perform pg_temp.assert(sqlerrm like 'Type changed%','Expected stale revision rejection');end;
 perform public.save_financial_type(jsonb_build_object('type_id',id,'revision',2,'name','Electricity revised','account','operating_expense','allocations',jsonb_build_object('lpg',50,'stove',50),'is_active',false));
 perform public.record_financial_entry(jsonb_build_object('reversal_of',entry,'wallet_id',w,'amount',10000,'date',d,'description','Actual supplier bill returned'),gen_random_uuid());
 perform pg_temp.assert((select balance=0 and (business_balances->>'lpg')::numeric=0 and (business_balances->>'stove')::numeric=0 from public.wallets where tenant_id=t and wallet_id=w),'Return after deactivation restores original 70/30 allocation');
 id:=(public.save_financial_type(jsonb_build_object('name','Shared small cost','account','operating_expense','allocations',jsonb_build_object('lpg',50,'stove',50)))->>'type_id')::uuid;
 entry:=(public.record_financial_entry(jsonb_build_object('type_id',id,'expected_revision',1,'wallet_id',w,'amount',0.03,'date',d,'description','Independent three cents'),gen_random_uuid())->>'entry_id')::uuid;
 for i in 1..3 loop perform public.record_financial_entry(jsonb_build_object('reversal_of',entry,'wallet_id',w,'amount',0.01,'date',d,'description','One cent actually returned'),gen_random_uuid());end loop;
 perform pg_temp.assert((select balance=0 and (business_balances->>'lpg')::numeric=0 and (business_balances->>'stove')::numeric=0 from public.wallets where tenant_id=t and wallet_id=w),'Three partial one-cent refunds restore exactly the original rounded business cents');
 begin perform public.record_financial_entry(jsonb_build_object('reversal_of',entry,'wallet_id',w,'amount',0.01,'date',d,'description','Over-return attempt'),gen_random_uuid());raise exception 'FAIL: over-return accepted';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;perform pg_temp.assert(sqlerrm like 'Return exceeds%','Expected over-return rejection');end;
 id:=(public.save_financial_type(jsonb_build_object('name','Shared workshop','account','equipment','allocations',jsonb_build_object('lpg',60,'stove',40)))->>'type_id')::uuid;
 r:=public.record_financial_entry(jsonb_build_object('type_id',id,'expected_revision',1,'wallet_id',w,'amount',100000,'date',d,'description','One shared workshop asset'),gen_random_uuid());asset:=(r->>'asset_id')::uuid;
 perform pg_temp.assert((select count(*)=1 from public.business_assets where tenant_id=t and asset_id=asset and cost=100000 and allocations='{"lpg":60,"stove":40}'::jsonb),'One custom equipment asset with shared ownership');
 perform public.accounting_operation(jsonb_build_object('action','asset_depreciate','asset_id',asset,'amount',1000,'date',d,'description','Shared workshop depreciation'),gen_random_uuid());
 id:=(public.save_financial_type(jsonb_build_object('name','Home family','account','withdrawals','allocations',jsonb_build_object('lpg',100)))->>'type_id')::uuid;
 perform public.record_financial_entry(jsonb_build_object('type_id',id,'expected_revision',1,'wallet_id',w,'amount',5000,'date',d,'description','Independently classified withdrawal'),gen_random_uuid());
 id:=(public.save_financial_type(jsonb_build_object('name','Other receipts','account','other_income','allocations',jsonb_build_object('logistics',100)))->>'type_id')::uuid;
 perform public.record_financial_entry(jsonb_build_object('type_id',id,'expected_revision',1,'wallet_id',w,'amount',2000,'date',d,'description','Independently classified revenue'),gen_random_uuid());
 id:=(public.save_financial_type(jsonb_build_object('name','Partners capital','account','capital','allocations',jsonb_build_object('lpg',60,'stove',40)))->>'type_id')::uuid;
 perform public.record_financial_entry(jsonb_build_object('type_id',id,'expected_revision',1,'wallet_id',w,'amount',100000,'date',d,'description','Independently classified capital'),gen_random_uuid());
 report:=public.get_finance_analysis(jsonb_build_object('business_id',t,'from',d,'to',d));
 perform pg_temp.assert((report->'totals'->>'revenue')::numeric=2000 and (report->'totals'->>'expenses')::numeric=1000 and (report->'totals'->>'profit')::numeric=1000,'Independent profit: revenue 2000 less depreciation 1000; equipment/capital/withdrawal excluded');
 perform pg_temp.assert((report->'totals'->>'contributions')::numeric=100000 and (report->'totals'->>'withdrawals')::numeric=5000,'Custom capital and withdrawal appear in correct period totals');
 perform pg_temp.assert((report->'totals'->>'position_profit')::numeric=1000,'Independent adjusted net assets explain custom-entry profit');
 perform pg_temp.assert((report->'period_values'->>'equipment_acquisitions')::numeric=100000,'Custom equipment is a period asset acquisition, without immediate expense');
 r:=public.get_accounting_breakdown(jsonb_build_object('business_id',t,'from',d,'to',d),'withdrawals','closing');
 perform pg_temp.assert(r->'entries'->0->>'type_name'='Home family' and (r->'entries'->0->>'amount')::numeric=5000,'Withdrawal component retains meaningful actual custom type');
 r:=public.get_wallet_ledger(jsonb_build_object('type',id,'business','stove'));
 perform pg_temp.assert((r->>'total')::integer=1 and r->'entries'->0->>'type_name'='Partners capital','Ledger filters use actual custom type catalog');
 perform pg_temp.assert(not exists(select 1 from public.accounting_lines where tenant_id=t group by journal_id,business_category having sum(amount)<>0),'Each business remains balanced for all custom types');
 begin perform public.save_financial_type(jsonb_build_object('name','Invalid allocation','account','operating_expense','allocations',jsonb_build_object('lpg',70,'stove',40)));raise exception 'FAIL: invalid total accepted';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;
 begin perform public.save_financial_type(jsonb_build_object('name','Invalid category','account','cash','allocations',jsonb_build_object('lpg',100)));raise exception 'FAIL: custom cash category accepted';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;
end $$;
set constraints all immediate;
select 'PASS: custom defaults, exact cents, historical snapshots, stale edits, deactivation, partial returns, shared equipment, capital/revenue/withdrawals and independent equation';
rollback;
